window.HERITAGE_POST_OFFICE_STATIONS=[{"id":"zone-1-square","zoneNumber":1,"zoneGroup":"outside","zoneBadge":"Bưu điện • Khu vực 1/6 (Bên ngoài)","title":"Trạm 1: Toàn cảnh Công trường Công xã Paris & Mặt tiền Bưu điện","shortLabel":"1. Quảng trường Bưu điện","mediaType":"image","isCustom":false,"folderTag":"Bưu điện Trung tâm Sài Gòn","imageSrc":"data:image/jpeg;base64,","videoSrc":null,"floorplanXY":{"x":110,"y":95},"defaultYaw":0,"defaultPitch":2,"narration":"Chào mừng thanh-sama đến với Trạm 1 bên ngoài Bưu điện Trung tâm Sài Gòn tại số 2 Công trường Công xã Paris, Quận 1. Từ khoảng sân rộng này, bạn có thể nhìn bao quát mặt tiền đối xứng phong cách Pháp cổ điển và lối vào Đường sách Nguyễn Văn Bình.","description":"Điểm xuất phát từ bên ngoài quảng trường Công trường Công xã Paris (tọa độ 10°46′48″N 106°42′00″E), nhìn thẳng vào mặt tiền vàng rực của Bưu điện Trung tâm Sài Gòn.","hotspots":[{"id":"hs-1-facade","yaw":0,"pitch":4,"type":"step","targetStationIndex":1,"label":"⬆️ Tiến vào Mặt tiền & Đồng hồ Bưu điện","detail":"Bước qua sân lát đá tiến thẳng tới cổng vòm chính của Bưu điện Trung tâm Sài Gòn."},{"id":"hs-1-arch","yaw":-26,"pitch":8,"type":"info","label":"🏛️ Kiến trúc Pháp 1886–1891","detail":"Tòa nhà Bưu điện Sài Gòn được xây dựng năm 1886–1891 theo đồ án của KTS Alfred Villedieu và Marie-Alfred Foulhoux."},{"id":"hs-1-bookstreet","yaw":34,"pitch":2,"type":"info","label":"📚 Cổng Đường sách Nguyễn Văn Bình","detail":"Bên hông phải tòa nhà Bưu điện là Đường sách TP.HCM rợp bóng cây xanh."}]},{"id":"zone-2-facade","zoneNumber":2,"zoneGroup":"outside","zoneBadge":"Bưu điện • Khu vực 2/6 (Mặt tiền & Cổng)","title":"Trạm 2: Mặt tiền Tân Phục Hưng, Đồng hồ Paris & Bảng Danh nhân","shortLabel":"2. Mặt tiền & Đồng hồ cổ","mediaType":"image","isCustom":false,"folderTag":"Bưu điện Trung tâm Sài Gòn","imageSrc":"data:image/jpeg;base64,","videoSrc":null,"floorplanXY":{"x":110,"y":76},"defaultYaw":0,"defaultPitch":4,"narration":"Tại Trạm 2 ngay trước cổng chính Bưu điện Trung tâm Sài Gòn, nổi bật nhất là chiếc đồng hồ lớn nhập từ Paris cùng phù điêu Tân Phục Hưng và các bảng tên vinh danh những nhà bác học ngành điện báo như Ampère, Volta, Faraday và Claude Chappe.","description":"Cận cảnh mặt tiền vàng rực của Bưu điện cùng chiếc đồng hồ cổ hơn 130 năm tuổi trên vòm cửa chính.","hotspots":[{"id":"hs-2-enter","yaw":0,"pitch":-3,"type":"step","targetStationIndex":2,"label":"⬆️ Bước qua Cổng chính vào Tiền sảnh Bưu điện","detail":"Đi qua cửa vòm cung để tiến vào Tiền sảnh nơi trưng bày hai bức bản đồ lịch sử năm 1892."},{"id":"hs-2-clock","yaw":0,"pitch":16,"type":"info","label":"🕰️ Đồng hồ Cổ Paris (1886–1891)","detail":"Chiếc đồng hồ trung tâm nhập từ Paris nằm dưới vòm phù điêu trang trí tinh xảo của Bưu điện."},{"id":"hs-2-scientists","yaw":-36,"pitch":8,"type":"info","label":"📜 Bảng tên Danh nhân Điện báo","detail":"Mặt tiền Bưu điện khắc tên các nhà phát minh vĩ đại: Claude Chappe, André-Marie Ampère, Alessandro Volta, Michael Faraday."}]},{"id":"zone-3-vestibule","zoneNumber":3,"zoneGroup":"vestibule","zoneBadge":"Bưu điện • Khu vực 3/6 (Tiền sảnh)","title":"Trạm 3: Tiền sảnh Vòm & Hai Bản đồ Lịch sử Vẽ tay Năm 1892","shortLabel":"3. Tiền sảnh & Bản đồ 1892","mediaType":"image","isCustom":false,"folderTag":"Bưu điện Trung tâm Sài Gòn","imageSrc":"data:image/jpeg;base64,","videoSrc":null,"floorplanXY":{"x":110,"y":60},"defaultYaw":0,"defaultPitch":0,"narration":"Bước qua cửa chính vào Trạm 3 là Tiền sảnh Bưu điện với hai bức bản đồ lịch sử vẽ tay từ năm 1892: bên phải là bản đồ Sài Gòn và vùng phụ cận năm 1892, bên trái là bản đồ mạng lưới đường dây điện báo Nam Kỳ và Campuchia năm 1892.","description":"Không gian tiền sảnh Bưu điện với sàn gạch bông cổ điển và hai bức bản đồ lịch sử khổng lồ vẽ tay năm 1892.","hotspots":[{"id":"hs-3-to-booths","yaw":20,"pitch":-4,"type":"step","targetStationIndex":3,"label":"⬆️ Qua Hành lang Bốt điện thoại gỗ","detail":"Di chuyển sang dãy hành lang bên trong Bưu điện để khám phá 14 cabin điện thoại gỗ cổ điển."},{"id":"hs-3-map-left","yaw":-38,"pitch":6,"type":"info","label":"🗺️ Bản đồ Saigon et ses environs 1892","detail":"Bản đồ quy hoạch Sài Gòn và vùng phụ cận năm 1892 vẽ tay trên vòm tường tiền sảnh Bưu điện."},{"id":"hs-3-map-right","yaw":44,"pitch":6,"type":"info","label":"⚡ Bản đồ Lignes télégraphiques 1892","detail":"Bản đồ mạng lưới tuyến cáp điện báo Nam Kỳ và Campuchia năm 1892."}]},{"id":"zone-4-booths","zoneNumber":4,"zoneGroup":"vestibule","zoneBadge":"Bưu điện • Khu vực 4/6 (Hành lang bên trong)","title":"Trạm 4: Dãy Cabin Điện thoại Gỗ Cổ & Bàn Viết thư Dương Văn Ngộ","shortLabel":"4. Bốt điện thoại gỗ cổ","mediaType":"image","isCustom":false,"folderTag":"Bưu điện Trung tâm Sài Gòn","imageSrc":"data:image/jpeg;base64,","videoSrc":null,"floorplanXY":{"x":50,"y":55},"defaultYaw":0,"defaultPitch":0,"narration":"Tại Trạm 4 dọc hành lang cánh bên của Bưu điện là dãy cabin điện thoại bằng gỗ gụ cổ điển có đồng hồ múi giờ quốc tế, cùng dãy bàn gỗ dài nơi cụ Dương Văn Ngộ từng ngồi viết thư thuê suốt từ năm 1990 đến năm 2021.","description":"Khu vực hành lang bên trong Bưu điện bảo tồn hệ thống cabin điện thoại công cộng bằng gỗ từ thời Pháp thuộc và dãy bàn viết thư.","hotspots":[{"id":"hs-4-to-mainhall","yaw":-28,"pitch":-2,"type":"step","targetStationIndex":4,"label":"⬆️ Tiến ra Giữa Đại sảnh Mái vòm Sắt","detail":"Bước ra trục chính giữa Đại sảnh Bưu điện dưới mái vòm sắt xanh lá cao vút."},{"id":"hs-4-phonebooths","yaw":-4,"pitch":4,"type":"info","label":"☎️ Dãy 14 Cabin Điện thoại Gỗ Cổ","detail":"Các buồng điện thoại gỗ chạm khắc cổ điển kèm dãy đồng hồ tròn phía trên."},{"id":"hs-4-writingdesk","yaw":22,"pitch":-8,"type":"info","label":"✍️ Bàn viết thư cụ Dương Văn Ngộ","detail":"Nơi người viết thư thuê cuối cùng tại Bưu điện Sài Gòn đã gắn bó hơn 30 năm (1990–2021)."}]},{"id":"zone-5-mainhall","zoneNumber":5,"zoneGroup":"inside","zoneBadge":"Bưu điện • Khu vực 5/6 (Giữa Đại sảnh)","title":"Trạm 5: Đại sảnh Mái vòm Sắt Xanh lá & Hai Dãy Quầy Bưu chính","shortLabel":"5. Giữa Đại sảnh vòm sắt","mediaType":"image","isCustom":false,"folderTag":"Bưu điện Trung tâm Sài Gòn","imageSrc":"data:image/jpeg;base64,","videoSrc":null,"floorplanXY":{"x":110,"y":38},"defaultYaw":0,"defaultPitch":4,"narration":"Tiến vào Trạm 5 ở chính giữa Đại sảnh Bưu điện Trung tâm Sài Gòn, không gian mở rộng với hệ mái vòm khung sắt sơn xanh lá và kem lấy cảm hứng từ các nhà ga xe lửa châu Âu thế kỷ 19 cùng hai dãy quầy gỗ giao dịch bưu chính hai bên.","description":"Trái tim kiến trúc bên trong Bưu điện Trung tâm Sài Gòn với kết cấu vòm cung chịu lực bằng trụ sắt thanh mảnh.","hotspots":[{"id":"hs-5-to-inner","yaw":0,"pitch":0,"type":"step","targetStationIndex":5,"label":"⬆️ Tiến tới Cuối Đại sảnh & Quầy Tem","detail":"Đi sâu vào khu vực trong cùng của Bưu điện dưới bức chân dung Chủ tịch Hồ Chí Minh."},{"id":"hs-5-vault","yaw":0,"pitch":24,"type":"info","label":"🏗️ Mái vòm Sắt Phong cách Gustave Eiffel","detail":"Hệ khung vòm sắt sơn xanh lá cây nâng đỡ toàn bộ mái vòm lấy sáng tự nhiên của Đại sảnh."},{"id":"hs-5-counters","yaw":32,"pitch":-5,"type":"info","label":"📮 Hai Dãy Quầy Giao dịch Bưu chính","detail":"Phục vụ gửi thư tín, bưu phẩm trong nước và quốc tế mỗi ngày."}]},{"id":"zone-6-sanctum","zoneNumber":6,"zoneGroup":"inside","zoneBadge":"Bưu điện • Khu vực 6/6 (Cuối Đại sảnh)","title":"Trạm 6: Tâm điểm Chân dung Chủ tịch Hồ Chí Minh & Quầy Tem Lưu niệm","shortLabel":"6. Cuối sảnh & Quầy Tem","mediaType":"image","isCustom":false,"folderTag":"Bưu điện Trung tâm Sài Gòn","imageSrc":"data:image/jpeg;base64,","videoSrc":null,"floorplanXY":{"x":110,"y":16},"defaultYaw":0,"defaultPitch":3,"narration":"Tại Trạm 6 — điểm sâu nhất bên trong Đại sảnh Bưu điện Trung tâm Sài Gòn, phía trên cao là bức chân dung lớn của Chủ tịch Hồ Chí Minh nhìn xuống toàn bộ sảnh chính, bên dưới là quầy gỗ vòng cung và các tủ trưng bày tem thư Việt Nam.","description":"Khu vực trong cùng của lộ trình tham quan Bưu điện từ ngoài vào trong: quầy bưu chính vòng cung trung tâm và khu trưng bày tem thư lưu niệm.","hotspots":[{"id":"hs-6-portrait","yaw":0,"pitch":14,"type":"info","label":"🇻🇳 Chân dung Chủ tịch Hồ Chí Minh","detail":"Bức chân dung lớn đặt trang trọng tại bức tường chính diện cuối đại sảnh Bưu điện."},{"id":"hs-6-stamps","yaw":-26,"pitch":-8,"type":"info","label":"💌 Tủ Trưng bày Tem thư & Bưu thiếp","detail":"Trưng bày các bộ tem bưu chính Việt Nam từ dấu mốc con tem 'Con Cò' năm 1864 đến nay."},{"id":"hs-6-loop-out","yaw":36,"pitch":-4,"type":"step","targetStationIndex":0,"label":"🔄 Quay ra Quảng trường Bưu điện (Trạm 1)","detail":"Hoàn thành trọn vẹn vòng tham quan từ ngoài vào trong Bưu điện và quay trở lại Công trường Công xã Paris."}]}];
